"""Runnable PyGObject program building the pipeline element by element."""

from __future__ import annotations

import json

from pipelab.catalog.store import Catalog
from pipelab.export.common import ElementSpec, PipelineSpec, PropertySpec, build_spec, camel_case
from pipelab.export.gst_launch import render_description
from pipelab.export.python_scripts import HARNESS, enabled_scripts, scripts_table
from pipelab.graph.models import Graph

_PRELUDE = '''#!/usr/bin/env python3
"""{name}: GStreamer pipeline generated by Pipelab.

Equivalent description (Gst.parse_launch / gst-launch-1.0):
    {description}

Embed it with ``{cls}().build()`` and drive it with ``start()``/``stop()``,
or run this file directly.
"""

from __future__ import annotations

import signal
import sys

import gi

gi.require_version("Gst", "1.0")
from gi.repository import GLib, Gst  # noqa: E402

try:  # PyGObject >= 3.52 moved unix signal helpers to GLibUnix
    gi.require_version("GLibUnix", "2.0")
    from gi.repository import GLibUnix  # noqa: E402

    unix_signal_add = GLibUnix.signal_add
except (ImportError, ValueError):
    unix_signal_add = GLib.unix_signal_add
{scripts_section}

class {cls}{bases}:
    """Owns the pipeline, its elements and the bus handling."""

    def __init__(self) -> None:
        self.pipeline: Gst.Pipeline | None = None
        self.elements: dict[str, Gst.Element] = {{}}
        self.loop: GLib.MainLoop | None = None
        self.exit_code = 0

    def build(self) -> Gst.Pipeline:
        """Create the elements, set their properties and link them."""
        self.pipeline = Gst.Pipeline.new({pipeline_name})
'''

_HELPERS = '''
    def _make(self, factory: str, name: str, properties: dict, parsed: dict) -> Gst.Element:
        element = Gst.ElementFactory.make(factory, name)
        if element is None:
            raise RuntimeError(f"element '{factory}' is not installed")
        self._configure(element, properties, parsed)
        self.pipeline.add(element)
        self.elements[name] = element
        return element

    @staticmethod
    def _configure(target: Gst.Object, properties: dict, parsed: dict) -> None:
        """Typed values use set_property; enums, flags, caps… are parsed like gst-launch."""
        for key, value in properties.items():
            target.set_property(key, value)
        for key, value in parsed.items():
            Gst.util_set_object_arg(target, key, value)

    def _link(self, src: str, src_pad: str, sink: str, sink_pad: str) -> None:
        if not self.elements[src].link_pads(src_pad, self.elements[sink], sink_pad):
            raise RuntimeError(f"could not link {src}.{src_pad} to {sink}.{sink_pad}")

    def _link_dynamic(self, src: str, src_pad: str, sink: str, sink_pad: str) -> None:
        """Link a *sometimes* pad (template or name ``src_pad``) once it appears."""
        sink_element = self.elements[sink]
        target = sink_element.get_static_pad(sink_pad) or sink_element.request_pad_simple(sink_pad)
        if target is None:
            raise RuntimeError(f"{sink} has no pad {sink_pad}")

        def on_pad_added(_element: Gst.Element, pad: Gst.Pad) -> None:
            template = pad.get_pad_template()
            if pad.get_name() != src_pad and (template is None or template.name_template != src_pad):
                return
            if target.is_linked() or not pad.query_caps(None).can_intersect(target.query_caps(None)):
                return
            if pad.link(target) != Gst.PadLinkReturn.OK:
                print(f"could not link {src}.{pad.get_name()} to {sink}.{sink_pad}", file=sys.stderr)

        self.elements[src].connect("pad-added", on_pad_added)

    def _configure_pad(self, element: str, pad: str, properties: dict, parsed: dict) -> None:
        target = self.elements[element].get_static_pad(pad)
        if target is None:
            raise RuntimeError(f"{element} has no pad {pad}")
        self._configure(target, properties, parsed)

    def _set_pad_reference(self, element: str, prop: str, pad: str) -> None:
        """GstPad-typed properties (e.g. input-selector active-pad) take a pad object."""
        self.elements[element].set_property(prop, self.elements[element].get_static_pad(pad))

    def start(self) -> None:
        if self.pipeline is None:
            self.build()
        bus = self.pipeline.get_bus()
        bus.add_signal_watch()
        bus.connect("message", self._on_message)
        if self.pipeline.set_state(Gst.State.PLAYING) == Gst.StateChangeReturn.FAILURE:
            raise RuntimeError("the pipeline refused to start")

    def stop(self) -> None:
        if self.pipeline is not None:
            self.pipeline.set_state(Gst.State.NULL)
            self.pipeline.get_bus().remove_signal_watch()

    def send_eos(self) -> None:
        """Ask sources to finish so muxers and files are finalised cleanly."""
        if self.pipeline is not None:
            self.pipeline.send_event(Gst.Event.new_eos())

    def _on_message(self, _bus: Gst.Bus, message: Gst.Message) -> None:
        if message.type == Gst.MessageType.ERROR:
            error, debug = message.parse_error()
            print(f"ERROR from {message.src.get_path_string()}: {error.message}", file=sys.stderr)
            print(f"  {debug}", file=sys.stderr)
            self.exit_code = 1
            self._quit()
        elif message.type == Gst.MessageType.WARNING:
            warning, _debug = message.parse_warning()
            print(f"WARNING from {message.src.get_path_string()}: {warning.message}", file=sys.stderr)
        elif message.type == Gst.MessageType.EOS:
            self._quit()

    def _quit(self) -> None:
        if self.loop is not None:
            self.loop.quit()

    def _on_sigint(self, *_args: object) -> bool:
        self.send_eos()
        return GLib.SOURCE_CONTINUE

    def run(self) -> int:
        """Play until end-of-stream or error; Ctrl+C sends EOS first."""
        self.loop = GLib.MainLoop()
        self.start()
        unix_signal_add(GLib.PRIORITY_DEFAULT, signal.SIGINT, self._on_sigint)
        try:
            self.loop.run()
        finally:
            self.stop()
        return self.exit_code


def main() -> int:
    Gst.init(sys.argv)
    return {cls}().run()


if __name__ == "__main__":
    sys.exit(main())
'''


def literal(value: object) -> str:
    if isinstance(value, bool | int | float):
        return repr(value)
    return json.dumps(value, ensure_ascii=False)


def _typed_value(spec: PropertySpec) -> object:
    if spec.kind in ("float", "double"):
        return float(spec.value)
    if spec.kind == "string":
        return str(spec.value)
    return spec.value


def _dicts(specs: tuple[PropertySpec, ...]) -> tuple[str, str]:
    typed = ", ".join(f"{literal(p.name)}: {literal(_typed_value(p))}" for p in specs if p.kind != "parse")
    parsed = ", ".join(f"{literal(p.name)}: {literal(p.text)}" for p in specs if p.kind == "parse")
    return f"{{{typed}}}", f"{{{parsed}}}"


def _make_line(element: ElementSpec) -> str:
    typed, parsed = _dicts(element.properties)
    return f"        self._make({literal(element.factory)}, {literal(element.name)}, {typed}, {parsed})"


def _build_body(spec: PipelineSpec, graph: Graph) -> list[str]:
    lines = [_make_line(element) for element in spec.elements]
    for link in spec.links:
        method = "_link_dynamic" if link.dynamic else "_link"
        args = (link.source.name, link.source_pad, link.target.name, link.target_pad)
        lines.append(f"        self.{method}({', '.join(literal(a) for a in args)})")
    for element in spec.elements:
        for pad, specs in element.pad_properties:
            typed, parsed = _dicts(specs)
            lines.append(
                f"        self._configure_pad({literal(element.name)}, {literal(pad)}, {typed}, {parsed})"
            )
        for ref in element.pad_refs:
            args = (element.name, ref.name, str(ref.value))
            lines.append(f"        self._set_pad_reference({', '.join(literal(a) for a in args)})")
    if enabled_scripts(graph):
        lines.append("        self._attach_scripts()")
    lines.append("        return self.pipeline")
    return lines


def _doc_text(text: str) -> str:
    """Text safe inside a triple-quoted docstring."""
    return text.replace("\\", "\\\\").replace('"""', '\\"\\"\\"')


def render(graph: Graph, catalog: Catalog, name: str) -> str:
    spec = build_spec(graph, catalog, name)
    stem = camel_case(name)
    cls = stem if stem.endswith("Pipeline") else f"{stem}Pipeline"
    has_scripts = bool(enabled_scripts(graph))
    prelude = _PRELUDE.format(
        name=_doc_text(name),
        description=_doc_text(render_description(graph, catalog) or "(empty)"),
        cls=cls,
        pipeline_name=literal(name),
        scripts_section=HARNESS + scripts_table(graph) if has_scripts else "",
        bases="(ProbeScriptsMixin)" if has_scripts else "",
    )
    return prelude + "\n".join(_build_body(spec, graph)) + "\n" + _HELPERS.replace("{cls}", cls)
